function Config.ExchangeData.data_shop_exchage_cost_fun(slot0)
	slot1 = Config.ExchangeData.data_shop_exchage_cost[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.ExchangeData.data_shop_exchage_cost[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

