function Config.ExchangeData.data_shop_exchage_hero_fun(slot0)
	slot1 = Config.ExchangeData.data_shop_exchage_hero[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.ExchangeData.data_shop_exchage_hero[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

